+            Ok(crate::commands::IpcResult::success(()))
+        }
+        Err(error) => {
+            log::error!("[acp-catalog] set_opt_in failure error={error}");
+            Ok(crate::commands::IpcResult::error(
+                error.to_string(),
+                "ACP_CATALOG_OPT_IN_FAILED",
