+            warn!(
+                target: "termul::web::install_api",
+                session = crate::logging::session_id(),
+                agent = %req.agent_id,
+                code,
+                msg = %error.message,
+                "install: failure"
+            );
+            (
+                StatusCode::OK,
+                Json(IpcBody::<InstallOutcome>::err(error.message, code)),
+            )
