+ * tests that construct this adapter directly.
+ */
+export function createTauriAcpInstallApi(): AcpInstallApi {
+  return {
+    async installAgent(agentId: string): Promise<IpcResult<InstallOutcome>> {
+      if (!isTauriContext()) {
+        return {
