+          error: 'acp_install_agent requires the Tauri runtime',
+          code: 'INVOKE_ERROR'
+        }
+      }
+      return invokeIpc<InstallOutcome>(IPC_COMMANDS.INSTALL_AGENT, {
+        request: { agentId }
+      })
+    }
+  }
+}

